using System;
using System.Collections.Generic;
using UnityEngine;

namespace Stardust
{
    // Data of the island generated by WorldGen (tools/make_map.py -> tools/export_unity.py), in Unity coordinates.
    // Loaded from Resources/World/world.json (JsonUtility: no nested arrays, so routes are flat x,y,z lists).

    [Serializable]
    public class WGate
    {
        public float[] p;
        public float[] dir;
        public float w;
        public string name;

        public Vector3 Pos => new Vector3(p[0], p[1], p[2]);
        public Vector3 Dir => new Vector3(dir[0], 0f, dir[1]).normalized;
        public bool Valid => p != null && p.Length == 3 && w > 0f;
    }

    [Serializable]
    public class WVariant
    {
        public string name;
        public int level;          // 0 tunnel, 1 ground, 2 high, 3 water
        public float hw;           // half width
        public float length;
        public float[] route;      // flat x,y,z
        public float[] jumps;      // distance along the route of each jump lip

        [NonSerialized] public Vector3[] pts;
        public Vector3[] Points
        {
            get
            {
                if (pts == null) pts = Flat(route);
                return pts;
            }
        }

        /// <summary>Route index of each jump lip (distances measured along the polyline).</summary>
        public static List<int> JumpIndices(Vector3[] pts, float[] jumps)
        {
            var o = new List<int>();
            if (jumps == null || jumps.Length == 0 || pts.Length < 2) return o;
            var acc = new float[pts.Length];
            for (int i = 1; i < pts.Length; i++) acc[i] = acc[i - 1] + Vector3.Distance(new Vector3(pts[i].x, 0f, pts[i].z), new Vector3(pts[i - 1].x, 0f, pts[i - 1].z));
            foreach (var j in jumps)
            {
                int best = 0;
                for (int i = 1; i < acc.Length; i++) if (Mathf.Abs(acc[i] - j) < Mathf.Abs(acc[best] - j)) best = i;
                o.Add(best);
            }
            return o;
        }

        public static Vector3[] Flat(float[] r)
        {
            if (r == null) return new Vector3[0];
            var a = new Vector3[r.Length / 3];
            for (int i = 0; i < a.Length; i++) a[i] = new Vector3(r[i * 3], r[i * 3 + 1], r[i * 3 + 2]);
            return a;
        }
    }

    [Serializable]
    public class WSection
    {
        public string key;
        public string title;
        public string biome;
        public WVariant[] variants;
    }

    [Serializable]
    public class WTunnel
    {
        public string name;
        public float[] p;
        public float yaw;
        public float len;
        public float[] tops;
        public float step;
        public float w;
        public float thw;
        public Vector3 Pos => new Vector3(p[0], p[1], p[2]);
    }

    [Serializable]
    public class WBridge
    {
        public string name;
        public float[] p;
        public float yaw;
        public float len, width, broken, deep;
        public Vector3 Pos => new Vector3(p[0], p[1], p[2]);
    }

    [Serializable]
    public class WAqueduct
    {
        public float[] p;
        public float yaw;
        public int n;
        public float seg, deck;
        public int[] missing;
        public Vector3 Pos => new Vector3(p[0], p[1], p[2]);
    }

    [Serializable]
    public class WWater
    {
        public float[] c;
        public float sx, sz, yaw, y;   // sx, sz = half sizes
    }

    [Serializable]
    public class WPlaced
    {
        public string name;
        public float[] p;
        public float yaw;   // degrees
        public float sc;
        public Vector3 Pos => new Vector3(p[0], p[1], p[2]);
        public Quaternion Rot => Quaternion.Euler(0f, yaw, 0f);
    }

    [Serializable]
    public class WZone
    {
        public string name;
        public string biome;
        public float[] c;
    }

    [Serializable]
    public class WEvent
    {
        public string id;
        public string name;
        public string type;      // circuit | drag | sprint
        public int laps;
        public float length;
        public float[] route;
        public float[] jumps;
        public WGate[] gates;
        public WGate start;
        public WGate finish;
    }

    [Serializable]
    public class WorldJson
    {
        public float size;
        public int res;
        public float cell;
        public float ground;
        public float waterY;
        public float fallY;
        public WZone[] zones;
        public WGate start;
        public WGate finish;
        public WGate[] checkpoints;
        public WSection[] sections;
        public WTunnel[] tunnels;
        public WBridge[] bridges;
        public WAqueduct[] aqueducts;
        public WWater[] waters;
        public WPlaced[] roofs;
        public float oceanY;
        public float oceanSize;
        public float[] oceanRects;
        public WPlaced[] props;
        public WPlaced[] colossi;
        public WPlaced[] islands;
        public WPlaced[] herds;
        public WPlaced[] grass;
        public WPlaced[] flowers;
        public WPlaced[] ferns;
        public WPlaced[] banners;
        public WPlaced[] pads;
        public WEvent[] events;
        public string[] vegTypes;
    }

    public struct VegInstance
    {
        public byte type;
        public Vector3 pos;
        public float yaw, scale;
    }

    public static class IslandData
    {
        public const string Root = "World/";
        static WorldJson cached;

        public static WorldJson Load()
        {
            if (cached != null) return cached;
            var ta = Resources.Load<TextAsset>(Root + "world");
            if (ta == null) { Debug.LogError("[Island] Resources/World/world.json is missing (run Stardust/Import World)"); return null; }
            cached = JsonUtility.FromJson<WorldJson>(ta.text);
            Resources.UnloadAsset(ta);
            return cached;
        }

        public static VegInstance[] LoadVeg()
        {
            var ta = Resources.Load<TextAsset>(Root + "veg");
            if (ta == null) return new VegInstance[0];
            var b = ta.bytes;
            int n = BitConverter.ToInt32(b, 0);
            var a = new VegInstance[n];
            int o = 4;
            for (int i = 0; i < n; i++)
            {
                a[i].type = b[o];
                a[i].pos = new Vector3(BitConverter.ToSingle(b, o + 1), BitConverter.ToSingle(b, o + 5), BitConverter.ToSingle(b, o + 9));
                a[i].yaw = BitConverter.ToSingle(b, o + 13);
                a[i].scale = BitConverter.ToSingle(b, o + 17);
                o += 21;
            }
            Resources.UnloadAsset(ta);
            return a;
        }
    }
}
